/**
 * \brief Where a chunk of a super-chunk stored in a contiguous frame on disk is in its file.
 *
 * This lets callers read (or ask the operating system to read ahead) the bytes of the chunks they will need,
 * e.g. in parallel, without reading any chunk to find them: the answer comes from the frame header and the chunk
 * index, which opening the frame has read already (and which stay in the page cache).
 *
 * @param schunk The super-chunk.
 * @param nchunk The chunk.
 * @param offset Position of its first byte in the file.
 * @param nbytes Its size in the file: the distance to the next chunk, which is the compressed size for chunks
 * written in order and otherwise at most the largest possible chunk size.  0 for chunks that the index codes as a
 * special value (zeros, NaNs, uninitialized), which have no bytes in the file.
 *
 * @return 0 on success, or a negative error code (e.g. for super-chunks in memory or in sparse frames).
 */
public static native int blosc2_schunk_get_chunk_range(blosc2_schunk schunk, @Cast("int64_t") long nchunk, @Cast("int64_t*") LongPointer offset,
                                               @Cast("int64_t*") LongPointer nbytes);
public static native int blosc2_schunk_get_chunk_range(blosc2_schunk schunk, @Cast("int64_t") long nchunk, @Cast("int64_t*") LongBuffer offset,
                                               @Cast("int64_t*") LongBuffer nbytes);
public static native int blosc2_schunk_get_chunk_range(blosc2_schunk schunk, @Cast("int64_t") long nchunk, @Cast("int64_t*") long[] offset,
                                               @Cast("int64_t*") long[] nbytes);

/**
 * \brief Decompress a single variable-length block from a schunk chunk.
 *
 * Convenience wrapper around #blosc2_vldecompress_block_ctx that fetches the
 * compressed chunk from \p schunk and decompresses only the requested VL block.
 * Only the requested block is allocated and decompressed; all other blocks in
 * the chunk are untouched.
 *
 * @param schunk The super-chunk from which to read.
 * @param nchunk Zero-based index of the chunk inside the super-chunk.
 * @param nblock Zero-based index of the VL block inside the chunk.
 * @param dest On success, points to a newly allocated buffer containing the
 *   decompressed block.  The caller is responsible for freeing it with \c free().
 * @param destsize On success, the uncompressed byte size of the block.
 *
 * @return The uncompressed byte size of the block on success, or a negative
 *   error code.  Returns #BLOSC2_ERROR_INVALID_PARAM if the chunk does not use
 *   VL blocks or if \p nblock is out of range.
 */
public static native int blosc2_schunk_get_vlblock(blosc2_schunk schunk, @Cast("int64_t") long nchunk,
                                           int nblock,
                                           @Cast("uint8_t**") PointerPointer dest, IntPointer destsize);
public static native int blosc2_schunk_get_vlblock(blosc2_schunk schunk, @Cast("int64_t") long nchunk,
                                           int nblock,
                                           @Cast("uint8_t**") @ByPtrPtr BytePointer dest, IntPointer destsize);
public static native int blosc2_schunk_get_vlblock(blosc2_schunk schunk, @Cast("int64_t") long nchunk,
                                           int nblock,
                                           @Cast("uint8_t**") @ByPtrPtr ByteBuffer dest, IntBuffer destsize);
