/**
 * \brief Get the internal blocksize to be used during compression. 0 means
 * that an automatic blocksize is computed internally.
 *
 * @return The size in bytes of the internal block size.
 */
public static native int blosc1_get_blocksize();

/**
 * \brief Force the use of a specific blocksize. If 0, an automatic
 * blocksize will be used (the default).
 *
 * \warning The blocksize is a critical parameter with important
 * restrictions in the allowed values, so use this with care.
 */
public static native void blosc1_set_blocksize(@Cast("size_t") long blocksize);


/**
  * \brief Set the split mode.
  <p>
  * @param splitmode It can take the next values:
  *  BLOSC_FORWARD_COMPAT_SPLIT
  *  BLOSC_AUTO_SPLIT
  *  BLOSC_NEVER_SPLIT
  *  BLOSC_ALWAYS_SPLIT
  *
  * BLOSC_FORWARD_COMPAT offers reasonably forward compatibility,
  * BLOSC_AUTO_SPLIT is for nearly optimal results (based on heuristics),
  * BLOSC_NEVER_SPLIT and BLOSC_ALWAYS_SPLIT are for the user experimenting
  *  when trying to get best compression ratios and/or speed.
  *
  * If not called, the default mode is BLOSC_FORWARD_COMPAT_SPLIT.
  *
  * This function should always succeed.
 */
public static native void blosc1_set_splitmode(int splitmode);

/**
 * \brief Make a compression context write Blosc1 chunks.
 *
 * The chunks use format version 2 and the 16-byte header, so that they can also be
 * decoded by C-Blosc 1.x.  They are not byte-identical to what C-Blosc 1.x would write.
 * Contexts do not write Blosc1 chunks by default.
 *
 * The chunk format has room for a plain shuffle or bitshuffle filter, in whichever slot of
 * the filter pipeline it is, and for the blosclz, lz4, lz4hc, zlib and zstd codecs.  A
 * compression call on a context that has any other filter or more than one filter, another
 * codec, a dictionary or variable-length blocks fails with an error.  A prefilter is applied
 * as usual: the chunk records nothing about it, so a reader gets the prefiltered data.
 *
 * @param context A compression context.
 * @param enable Whether to write Blosc1 chunks.
 *
 * @return 0 on success, a negative error code otherwise.
 *
 * @see #blosc2_ctx_get_blosc1_format
 */
public static native int blosc2_ctx_set_blosc1_format(blosc2_context context, @Cast("bool") boolean enable);

